import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BvlN9b-o.js";const m=JSON.parse('{"title":"Compose and remove reference examples","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/example-removal","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/example-removal.md","filePath":"en/tutorials/example-removal.md"}'),n={name:"en/tutorials/example-removal.md"};function o(r,e,l,d,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="compose-and-remove-reference-examples" tabindex="-1">Compose and remove reference examples <a class="header-anchor" href="#compose-and-remove-reference-examples" aria-label="Permalink to &quot;Compose and remove reference examples&quot;">​</a></h1><p>The template registers only the knowledge base (a full business) by default; notes (a minimal example that exists only to prove the composition interface) ships with the repository but unregistered — the add tool <code>scripts/example-add.mjs</code> from <a href="./add-example">the wiring chapter</a> registers it at any time. This chapter answers &quot;how does this template become my product&quot;: first see what an example owns, then preview a removal, delete <strong>any one</strong> example, or remove all the way down to zero — source, routes, migration registration, jobs and tutorial navigation disappear together, while Core (registration/login, members, file service, jobs, notifications, API keys, audit, mail, rate limiting, telemetry) stays intact and keeps being verified. For the frontend wiring and how the four app combinations run, see <a href="./add-example">Add a reference example</a>; this chapter focuses on the removal side: tooling, protections and boundaries.</p><h2 id="_1-the-ownership-manifest-what-an-example-actually-owns" tabindex="-1">1. The ownership manifest: what an example actually owns <a class="header-anchor" href="#_1-the-ownership-manifest-what-an-example-actually-owns" aria-label="Permalink to &quot;1. The ownership manifest: what an example actually owns&quot;">​</a></h2><p>Each example registers five kinds of information in <code>examples/&lt;id&gt;/manifest.json</code>, and every kind is pinned by a checker. Take the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">knowledge base</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/examples/notes/manifest.json" target="_blank" rel="noreferrer">notes</a> manifests:</p><table tabindex="0"><thead><tr><th>Item</th><th>Content</th><th>Enforced by</th></tr></thead><tbody><tr><td><code>ownedPaths</code></td><td>Backend modules, views, migrations, tests, E2E and tutorial pages the example deletes wholesale</td><td><code>pnpm boundaries:check</code>, manifest tests</td></tr><tr><td><code>registrationMarkers</code></td><td><code>example:&lt;prefix&gt;:*:start/end</code> registration blocks in the assembly files</td><td>Same, must be intact pairs</td></tr><tr><td><code>compositionPoints</code></td><td>Files that must be edited (not deleted): API/Worker/Web/docs navigation</td><td>Existence check</td></tr><tr><td><code>ownedDependencies</code></td><td>npm dependencies only this example uses (such as react-markdown)</td><td>Stripped from the package.json on removal</td></tr><tr><td><code>ownedCargoDependencies</code></td><td>Rust dependencies only this example uses (zip, pulldown-cmark)</td><td>Stripped from the Cargo.toml on removal</td></tr></tbody></table><p>Exclusivity is a hard constraint: two examples claiming the same <code>ownedPaths</code> entry, or the same exclusive dependency in the same manifest, is an ownership conflict the removal tool could never adjudicate, so verification fails right there and names both sides — and the removal command runs that same verification before touching a single byte. The reverse holds too: Core modules (including the later mail and telemetry modules) <strong>never import an example</strong>, and examples never reference each other — not even via the shared views barrel. <code>boundaries:check</code> scans import directions, table ownership inside SQL strings and cross-module view references file by file; shortcuts like writing an example into Identity fail at the checker. Every module&#39;s <code>module.json</code> declares its own tables (such as <code>knowledge.documents</code>), and every table appearing in a migration must have an owner.</p><h2 id="_2-dry-run-see-exactly-what-would-happen-first" tabindex="-1">2. Dry-run: see exactly what would happen first <a class="header-anchor" href="#_2-dry-run-see-exactly-what-would-happen-first" aria-label="Permalink to &quot;2. Dry-run: see exactly what would happen first&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                  # removes the knowledge example by default</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-add.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # notes ships unregistered; add it back first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # then preview removing notes</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/example-remove.mjs" target="_blank" rel="noreferrer">removal tool</a> lists every path it would delete, every marker block it would strip, the tutorial pages that would leave the navigation, the dependencies it would prune and the regeneration commands to rerun afterwards — <strong>without writing anything</strong>. Pick the example explicitly with <code>--example &lt;id&gt;</code>; an unknown id fails immediately with the list of registered ids, never silently acting on &quot;the closest match&quot;.</p><p>The protections are hard, and a refusal hands you a list instead of an overwrite: uncommitted changes are listed and the tool refuses to touch a byte; a registration marker block edited out of an intact start/end pair is refused with its location. The tool only operates on clean git working copies — the same care protects your customizations: commit or discard your changes first, or untangle the parts interwoven with the example.</p><h2 id="_3-remove-any-one-example-or-all-the-way-to-zero" tabindex="-1">3. Remove any one example, or all the way to zero <a class="header-anchor" href="#_3-remove-any-one-example-or-all-the-way-to-zero" aria-label="Permalink to &quot;3. Remove any one example, or all the way to zero&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       # remove knowledge (the default source registers knowledge only → zero examples)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-add.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # add notes back → dual</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # remove knowledge → notes only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # remove notes → Core only</span></span></code></pre></div><p>The tool executes exactly what the manifest describes: it deletes the owned paths, strips the marker blocks from the assembly points (routes and OpenAPI registration in <code>apps/api/src/lib.rs</code>, job registration in <code>apps/worker/src/main.rs</code>, web routes and view exports, tutorial navigation), removes the tutorial page from <code>docs/site.json</code>, prunes the example-exclusive dependencies, sets the manifest to <code>status: removed</code> (the manifest itself stays — scripts like desktop-smoke adapt by it), and finally regenerates the derived artifacts in place: <code>pnpm install</code>, <code>cargo update --workspace</code>, <code>pnpm generate</code> (OpenAPI/contracts/SDK) and the project docs references.</p><p>To remove several examples, run them <strong>one at a time and commit the copy between removals</strong> — the tool only edits clean copies, which is also how it protects you. Once every example is gone only Core remains and login lands on the universal home; when the example declaring the default entry is removed (the knowledge example&#39;s &quot;My documents&quot; today), the login landing falls back to the universal home just as naturally, with no entry left pointing at a deleted page. Every removal is accepted against the same gates:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-core</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # fmt, clippy, backend tests, contracts drift, boundary checks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # the docs site build; dead links surface here</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saas/web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>Migration history has two paths, and the tool defaults to the <strong>conservative</strong> one:</p><ul><li><strong>Projects whose migrations have run or shipped</strong>: do nothing. The example-owned migrations stay exactly as they are, with the <code>_sqlx_migrations</code> history intact — removing source code never means deleting business data; the tables those migrations describe stay in the database until you handle them explicitly with a <strong>new migration</strong>. The retention path also registers these files under the manifest&#39;s <code>retainedMigrations</code>: their tables no longer have a code owner, so the table-ownership checker exempts exactly those historical files while the &quot;every table must have an owner&quot; rule keeps applying to everything else.</li><li><strong>Brand-new projects (no database yet)</strong>: <code>just example-remove --trim-migrations</code> cuts the example migrations out so a fresh empty database initializes from the Core migrations alone. Trimming is only legitimate for copies that never applied these migrations; the CI removal acceptance takes this path and verifies it against a real empty database.</li></ul><h2 id="_4-what-core-keeps-and-what-leaves" tabindex="-1">4. What Core keeps, and what leaves <a class="header-anchor" href="#_4-what-core-keeps-and-what-leaves" aria-label="Permalink to &quot;4. What Core keeps, and what leaves&quot;">​</a></h2><p>Registration/login and sessions, organization members, the file service and object cleanup, jobs and recovery, notifications, API keys, audit, password-reset mail, rate limiting, telemetry — all stay, each pinned by tests: <code>just check-core</code> after a removal runs exactly these surviving tests (<code>registration</code>, <code>members</code>, <code>jobs</code>, <code>config</code>, <code>migration</code>). The mail and telemetry modules are in no <code>ownedPath</code>, which the handover notes call out as an acceptance point.</p><p>History does not vanish with the source: notifications pointing at a removed business show &quot;this feature is currently unavailable&quot; instead of a clickable target, and old bookmarks or external deep links land on the &quot;this feature is currently unavailable&quot; page, which keeps an explicit way back home — the address is never rewritten silently. The production tooling layers cleanly: <code>production-backup</code> and <code>production-restore</code> are business-agnostic (they only speak database and object inventory) and work as usual after a removal; the seeded journeys of <code>production-smoke</code> and <code>production-restore-drill</code> ride on example data, so after a removal they say so honestly and exit, inviting you to write your own drill on the same skeleton — the backup data plane is unchanged; only the journey is.</p><p>Performance budgets layer along the same line: the registration budget (<code>perf_registration.rs</code>) belongs to Core and stays pinned by backend tests after a removal; the document list/create/export budgets (<code>perf_documents.rs</code>) and the example list SQL in the query-plan scripts leave with the example — swap in your own business&#39;s performance tests for <code>just perf</code>, and the query-plan scripts in <code>just perf-ci</code> say so honestly and exit.</p><p>CI rehearses all of this on every PR: it clones the template into a temporary copy and dirties a file to verify the protection refuses; in the first copy it runs the frontend gates on the default (knowledge-only) assembly, registers notes with the add tool and commits, runs the full gate set on the dual combination, then actually removes knowledge with <code>--trim-migrations</code> for the notes-only combination against the full gate set, and removes notes again for the Core-only combination with the frontend gates rerun; in a second copy it removes notes for the knowledge-only combination, also against the full gate set. All four combinations are built and tested — before the job finishes with the next section&#39;s wiring exercise.</p><h2 id="_5-wire-in-your-own-business" tabindex="-1">5. Wire in your own business <a class="header-anchor" href="#_5-wire-in-your-own-business" aria-label="Permalink to &quot;5. Wire in your own business&quot;">​</a></h2><p>Deleting an example is only the beginning; the tutorial&#39;s promise is &quot;a new business joins through the same public interfaces&quot;. For the frontend pages and navigation, see <a href="./add-example">Add a reference example</a>; the backend follows these steps:</p><ol><li><strong>Your own model and migration</strong>: create <code>migrations/00XX_&lt;business&gt;.sql</code>, create your schema and tables, and register table ownership in <code>module.json</code> (<code>boundaries:check</code> requires every table to have an owner; referencing stable Core identifiers like <code>saas_core.users(id)</code> is an allowed cross-module reference).</li><li><strong>Implement the module</strong>: declare it in <code>crates/app/src/modules/mod.rs</code> and write the HTTP handlers (get the current user with <code>identity::require_session</code>) and domain queries in <code>crates/app/src/modules/&lt;business&gt;/</code>; a module never touches another module&#39;s private tables. Keep identifiers as strings and convert explicitly at the SQL boundary (<code>$1::uuid</code>, <code>RETURNING id::text</code>) — the workspace&#39;s sqlx does not enable the uuid codec feature.</li><li><strong>Register routes and OpenAPI</strong>: merge the module&#39;s router into <code>domain_routes</code> and its openapi() into the docs at the assembly point in <code>apps/api/src/lib.rs</code>.</li><li><strong>Generate the SDK</strong>: <code>pnpm generate</code> puts your resource types into contracts/SDK.</li><li><strong>Test</strong>: assert register → create → read over the public HTTP interface like <code>apps/api/tests/notes.rs</code> does (<code>#[sqlx::test]</code> needs a PostgreSQL; <code>just test-backend</code> brings a disposable instance).</li></ol><p>The exercise script (<code>scripts/example-new-business.mjs</code>) writes these files into a temporary copy for you and runs <code>cargo test</code> and clippy through <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/lib/postgres.mjs" target="_blank" rel="noreferrer">the same test-postgres channel</a> — a green CI run is the executable proof that the wiring path works after a removal.</p><h2 id="_6-run-this-chapter-s-checks" tabindex="-1">6. Run this chapter&#39;s checks <a class="header-anchor" href="#_6-run-this-chapter-s-checks" aria-label="Permalink to &quot;6. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/example-remove.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Drift between the manifests and the working copy is pinned at two layers: <code>boundaries:check</code> verifies the registered paths, their exclusivity and the marker blocks on every <code>just check</code>, and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">manifest tooling tests</a> verify the removal semantics themselves on a synthetic copy — zero-write dry-runs, exact deletions and marker edits, refusals for unknown ids and ownership conflicts, navigation trimming, dependency stripping, migrations retained by default versus <code>--trim-migrations</code>, and the refusal of dirty copies and structurally broken markers. The real removal acceptance runs end to end on a fresh copy in the CI <code>example-removal</code> job.</p><hr><p>Source version：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/tutorials/23-example-removal.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,31)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
